struct Orders: RandomAccessCollection {
    private var storage: [Order] = []          // private: no container leak
    var startIndex: Int { storage.startIndex }
    var endIndex: Int { storage.endIndex }
    subscript(i: Int) -> Order { storage[i] }

    mutating func add(_ order: Order) throws { // the only mutating path
        guard storage.count < maxOrders else { throw OrderError.limitReached }
        storage.append(order)
    }
    var total: Money { storage.reduce(.zero) { $0 + $1.amount } }
}
